-- Issue #202 : barème serveur de l'épreuve écrite Bac 2024 (session de contrôle).
-- Idempotente : la ligne est insérée ou mise à jour. Sans elle, la remise de la copie de cette
-- épreuve n'aurait pas de référence côté serveur (voir la migration 0033).
insert into public.sujets_examen_ecrit_baremes (exam_id, titre, duree_min, bareme_total, sections_meta)
values
  ('exam-bac2024-controle-ecrit', 'Bac 2024 (Session de Contrôle) - Épreuve Écrite Systèmes & Technologies de l''Informatique', 180, 20, $json$[{"id":"exercice-1-qcm","title":"Exercice N°1 : QCM Notions Web & Programmation (2 pts)","type":"qcm","pointsMax":2,"questions":[{"id":"EX1-Q1","points":0.25,"multiple":false,"correctAnswers":["opt-onfocus"],"explanation":"onfocus se déclenche quand le champ reçoit le focus (devient actif) ; onblur à la perte du focus, oninput à chaque saisie."},{"id":"EX1-Q2","points":0.25,"multiple":false,"correctAnswers":["opt-figure"],"explanation":"<figcaption> est la légende de l'élément <figure> qui la contient."},{"id":"EX1-Q3","points":0.25,"multiple":false,"correctAnswers":["opt-incliner"],"explanation":"skew(ax, ay) incline l'élément selon l'axe X puis l'axe Y : ce n'est ni un déplacement ni une rotation."},{"id":"EX1-Q4","points":0.25,"multiple":false,"correctAnswers":["opt-casse"],"explanation":"text-transform: uppercase | lowercase | capitalize modifie la casse du texte."},{"id":"EX1-Q5","points":0.25,"multiple":false,"correctAnswers":["opt-document-write"],"explanation":"document.write() écrit dans le document ; alert() et prompt() ouvrent des boîtes de dialogue."},{"id":"EX1-Q6","points":0.25,"multiple":false,"correctAnswers":["opt-checkdate"],"explanation":"checkdate(mois, jour, année) vérifie qu'une date du calendrier grégorien est valide."},{"id":"EX1-Q7","points":0.25,"multiple":false,"correctAnswers":["opt-isset"],"explanation":"isset() teste qu'une variable (y compris un tableau) existe et n'est pas NULL."},{"id":"EX1-Q8","points":0.25,"multiple":false,"correctAnswers":["opt-unique"],"explanation":"CHECK et DEFAULT restreignent le domaine des valeurs ; UNIQUE interdit les doublons, c'est une contrainte d'unicité."}]},{"id":"exercice-2-collecte","title":"Exercice N°2 : Base BD_Collecte - Poubelles intelligentes (5 pts)","type":"modeling","pointsMax":5,"questions":[{"id":"EX2-REP-1","points":1.5,"type":"representation","explanation":"Poubelle 1,N Remplissage ; Poubelle 1,N Collecte ; Agent 1,N Collecte. Clés primaires : idPoub ; (dateRemp, idPoub) ; idAg ; (dateCol, idPoub). Clés étrangères : idPoub dans Remplissage et Collecte, idAg dans Collecte."},{"id":"EX2-VF-A","points":0.25,"type":"code_analysis","explanation":"Vrai : nomRue est un attribut de Poubelle, chaque poubelle n'a donc qu'une seule rue."},{"id":"EX2-VF-B","points":0.25,"type":"code_analysis","explanation":"Faux : la clé de Collecte est (dateCol, idPoub) ; un même agent peut collecter plusieurs poubelles."},{"id":"EX2-VF-C","points":0.25,"type":"code_analysis","explanation":"Vrai : dateRemp contient la date et l'heure, plusieurs relevés d'une même poubelle sont possibles dans la journée."},{"id":"EX2-VF-D","points":0.25,"type":"code_analysis","explanation":"Faux : poids est le poids d'une seule poubelle collectée (une ligne de Collecte)."},{"id":"EX2-VF-E","points":0.25,"type":"code_analysis","explanation":"Faux : dateCol est une date sans heure et la clé primaire (dateCol, idPoub) interdit deux collectes le même jour."},{"id":"EX2-EXT-1","points":1.25,"type":"representation","explanation":"Rue(#idRue, nomRue) et Poubelle(#idPoub, volMax, idRue#) : la clé primaire de Rue migre en clé étrangère dans Poubelle."},{"id":"EX2-EXT-2","points":1.0,"type":"representation","explanation":"Agent(#idAg, nomAg, telAg), Vehicule(#idVeh, capMax, idAg#), Collecte(#dateCol, #idPoub, poids, idVeh#) : l'agent est atteint par le véhicule, Collecte ne référence plus idAg."}]},{"id":"exercice-3-html","title":"Exercice N°3 - 1ère partie, I : Analyse du code HTML (1.25 pt)","type":"qcm","pointsMax":1.25,"questions":[{"id":"EX3-HTML-1","points":0.25,"multiple":false,"correctAnswers":["opt-html"],"explanation":"En HTML5 la déclaration est simplement <!DOCTYPE html>."},{"id":"EX3-HTML-2","points":0.25,"multiple":false,"correctAnswers":["opt-principal"],"explanation":"Le pied de page est <footer> (ligne 41) et la navigation est <nav> (ligne 11) : <section> porte le contenu principal."},{"id":"EX3-HTML-3","points":0.25,"multiple":false,"correctAnswers":["opt-summary"],"explanation":"<summary> fournit le titre cliquable d'un bloc <details>."},{"id":"EX3-HTML-4","points":0.25,"multiple":false,"correctAnswers":["opt-toujours"],"explanation":"Sans return, la valeur de valide() est ignorée : le formulaire est toujours soumis."},{"id":"EX3-HTML-5","points":0.25,"multiple":false,"correctAnswers":["opt-name"],"explanation":"Des boutons radio ne sont exclusifs que s'ils partagent le même name ; ici name=\"like\" et name=\"dislike\"."}]},{"id":"exercice-3-web","title":"Exercice N°3 - 1ère partie, II à IV : Analyse du code CSS, JavaScript et PHP (4.75 pts)","type":"code_analysis","pointsMax":4.75,"questions":[{"id":"EX3-CSS-1","points":0.5,"type":"code_analysis","explanation":"Sélecteur de classe (.video) ; règle non liée à un événement (Faux) ; la vidéo devient semi-transparente (opacité 50 %)."},{"id":"EX3-CSS-2","points":0.5,"type":"code_analysis","explanation":"Sélecteur d'élément (video) avec la pseudo-classe :hover ; règle liée à un événement (Vrai) ; la vidéo est agrandie de 20 % (scale 1.2) au survol."},{"id":"EX3-CSS-3","points":0.5,"type":"code_analysis","explanation":"Sélecteur d'identifiant (#video1) ; règle non liée à un événement (Faux) ; la vidéo reçoit une bordure continue."},{"id":"EX3-CSS-4","points":0.25,"type":"code_analysis","explanation":"div1 a la classe zone (règle 4), l'identifiant div1 (règle 6) et figure dans le groupe de sélecteurs de la règle 9."},{"id":"EX3-JS-1","points":0.5,"type":"code_analysis","explanation":"ch = ch.replace(ch.charAt(0), ch.charAt(0).toUpperCase()) met la première lettre en majuscule : « Bravo »."},{"id":"EX3-JS-2","points":0.5,"type":"code_analysis","explanation":"comment.trim() supprime les espaces situés au début et à la fin du commentaire."},{"id":"EX3-JS-3","points":0.5,"type":"code_analysis","explanation":"formater() n'est appelée que si le commentaire (après trim) n'est pas vide : seul le 1er aperçu convient."},{"id":"EX3-JS-4","points":0.5,"type":"code_analysis","explanation":"Dans le champ de saisie de texte d'identifiant « comment » (propriété value)."},{"id":"EX3-PHP-1","points":0.5,"type":"code_analysis","explanation":"Aucun mot filtré n'est trouvé : la boucle va jusqu'au bout, $i = 3, $trouve = false et $unMot = \"urgent\"."},{"id":"EX3-PHP-2","points":0.5,"type":"code_analysis","explanation":"Le mot « offre » est trouvé au 2e tour : $i = 2, $trouve = true et $unMot = \"offre\"."}]},{"id":"exercice-3-bdd","title":"Exercice N°3 - 2ème partie : Base StreamVision - Interprétation et requêtes SQL (7 pts)","type":"sql","pointsMax":7,"questions":[{"id":"EX3-BDD-R1","points":0.5,"type":"code_analysis","explanation":"PgmAlgo totalise 30 + 40 = 70 min (> 60) ; WebX totalise 30 min, Crypto4tous n'a aucune vidéo : une seule ligne (PgmAlgo, 70)."},{"id":"EX3-BDD-R2","points":0.5,"type":"code_analysis","explanation":"Elle affiche le nom des chaînes et la durée totale de leurs vidéos, pour les chaînes dont cette durée totale dépasse 60 minutes."},{"id":"EX3-SQL-LID-1","points":0.5,"type":"query","explanation":"Projection simple sur la table Chaine."},{"id":"EX3-SQL-LID-2","points":0.5,"type":"query","explanation":"Sélection dans Visualisation sur idVideo = 2438."},{"id":"EX3-SQL-LID-3","points":0.5,"type":"query","explanation":"Jointure Video-Chaine sur idChaine puis filtre sur nomChaine."},{"id":"EX3-SQL-LID-4","points":0.5,"type":"query","explanation":"Jointure Visualisation-Utilisateur et fonction MAX sur dateVis."},{"id":"EX3-SQL-LID-5","points":0.5,"type":"query","explanation":"Jointure Video-Chaine et fonction SUM sur taille."},{"id":"EX3-SQL-LID-6","points":0.75,"type":"query","explanation":"Jointure VideosTag-Visualisation, GROUP BY idVideo, COUNT(*) et ORDER BY décroissant."},{"id":"EX3-SQL-LID-7","points":0.75,"type":"query","explanation":"Sous-requête scalaire avec AVG(duree) sur la même chaîne."},{"id":"EX3-SQL-LMD-1","points":0.5,"type":"dml","explanation":"INSERT en omettant idTag (auto-incrémenté) : INSERT INTO Tag (libelleTag) VALUES ('HTMX');"},{"id":"EX3-SQL-LMD-2","points":0.5,"type":"dml","explanation":"DELETE FROM Video WHERE idChaine = 3;"},{"id":"EX3-SQL-LMD-3","points":0.5,"type":"dml","explanation":"UPDATE Visualisation SET commentaire = '***' WHERE idVideo = 2216 AND commentaire LIKE '%la fin du film%';"},{"id":"EX3-SQL-LDD-4","points":0.5,"type":"ddl","explanation":"ALTER TABLE Video ADD langue CHAR(2);"}]}]$json$::jsonb)
on conflict (exam_id) do update set
  titre = excluded.titre,
  duree_min = excluded.duree_min,
  bareme_total = excluded.bareme_total,
  sections_meta = excluded.sections_meta;
